### src/services/googleOAuth.ts
import { OAuth2Client } from "google-auth-library";
import { authConfig } from "../config/auth";
import type { AuthSession } from "../types/auth";

const client = new OAuth2Client(authConfig.clientId, authConfig.clientSecret);

export async function googleOAuthCallback(code: string): Promise<AuthSession> {
  const ticket = await client.verifyIdToken({ idToken: code, audience: authConfig.clientId });
  const payload = ticket.getPayload();
  return { provider: "google", email: payload?.email ?? "" };
}


### src/services/stripeBilling.ts
import Stripe from "stripe";
import { stripeConfig } from "../config/stripe";
import type { BillingCheckout } from "../types/billing";

const stripe = new Stripe(stripeConfig.secretKey);

export async function createSubscription(customerId: string, priceId: string): Promise<BillingCheckout> {
  const session = await stripe.checkout.sessions.create({
    customer: customerId,
    line_items: [{ price: priceId, quantity: 1 }],
    mode: "subscription"
  });
  return { id: session.id, url: session.url ?? "" };
}


### src/types/auth.ts
export interface AuthSession {
  provider: "google";
  email: string;
}


### src/types/billing.ts
export interface BillingCheckout {
  id: string;
  url: string;
}

